            entity_column = DOC_ENTITY_COLUMN.get(doc_name, "CASE_NUMBER")

            matching_rows = [r for r in doc_rows if r.get(entity_column, "").strip() == entity]

            if not matching_rows:
                pair_result[fact_name] = "ABSENT"
                continue

            values = []
            for row in matching_rows:
